enum TomlValue {
  TomlString(String)
  TomlInt(Int64)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
  TomlTable(Map[String, TomlValue])
}

/// Parse TOML text into a JSON value
pub fn parse(text : String) -> Json raise ParseError {
  let mut table = Map::new()
  let mut current_path : Array[String] = []

  for line in text.split("\n") {
    let line = line.trim()
    // Skip blank lines and comments
    if line.is_empty() || line[0] == '#' {
      continue
    }

    // Check for table header
    if line[0] == '[' {
      let close = line.index_of(']', 1)
      if close == -1 {
        raise ParseError::InvalidSyntax("unclosed table bracket: \{line}")
      }
      let key_part = line.sub(start=1, end=close).to_owned()
      let remainder = line.sub(start=close + 1, end=line.length()).to_owned().trim()
      if not remainder.is_empty() && remainder[0] != '#' {
        raise ParseError::InvalidSyntax(
          "trailing junk after table header: \{remainder}",
        )
      }
      current_path = parse_dotted_key(key_part)?
      // Ensure the intermediate path exists as a table
      ensure_table(table, current_path)?
      continue
    }

    // Key-value pair
    let eq_pos = line.index_of('=', 0)
    if eq_pos == -1 {
      raise ParseError::InvalidSyntax("expected key=value, got: \{line}")
    }
    let key_str = line.sub(start=0, end=eq_pos).to_owned().trim()
    let val_str = line.sub(start=eq_pos + 1, end=line.length()).to_owned().trim()
    let key_parts = parse_dotted_key(key_str)?
    let val = parse_value(val_str)?

    // Full path is current_path + key_parts
    let full_path = current_path + key_parts
    let existing = table.insert(full_path, val)
    if existing is Some(_) {
      let path_str = full_path.join(".")
      raise ParseError::DuplicateKey(path_str)
    }
  }

  build_json(table)
}

/// Parse a dotted key string like "owner.name" into parts
fn parse_dotted_key(s : String) -> Array[String] raise ParseError {
  if s.is_empty() {
    raise ParseError::InvalidSyntax("empty key")
  }
  let mut parts : Array[String] = []
  let mut start = 0
  let len = s.length()
  while start < len {
    if s[start] == '.' {
      start += 1
      continue
    }
    let mut end = start
    while end < len && s[end] != '.' {
      end += 1
    }
    let part = s.sub(start=start, end=end).to_owned()
    if part.is_empty() {
      raise ParseError::InvalidSyntax("empty key segment in: \{s}")
    }
    parts.push(part)
    start = end
  }
  parts
}

/// Parse a TOML value
fn parse_value(s : String) -> TomlValue raise ParseError {
  let s = s.trim()
  if s.is_empty() {
    raise ParseError::InvalidSyntax("empty value")
  }

  // Array
  if s[0] == '[' {
    return parse_array(s)
  }

  // String
  if s[0] == '"' {
    return TomlString(parse_string(s))
  }

  // Boolean
  if s == "true" {
    return TomlBool(true)
  }
  if s == "false" {
    return TomlBool(false)
  }

  // Integer
  let n : Int64? = @string.parse_int64(s) catch { _ => None }
  if n is Some(v) {
    return TomlInt(v)
  }

  raise ParseError::InvalidSyntax("unrecognised value: \{s}")
}

/// Parse a TOML quoted string with escape sequences
fn parse_string(s : String) -> String raise ParseError {
  if s.length() < 2 || s[0] != '"' {
    raise ParseError::InvalidSyntax("expected quoted string, got: \{s}")
  }
  let mut i = 1
  let mut result = StringBuilder::new()
  let len = s.length()
  let bytes = s
  while i < len && bytes[i] != '"' {
    if bytes[i] == '\\' {
      i += 1
      if i >= len {
        raise ParseError::InvalidSyntax("unterminated escape in string")
      }
      match bytes[i] {
        '"' => result.write_char('"')
        '\\' => result.write_char('\\')
        'n' => result.write_char('\n')
        't' => result.write_char('\t')
        _ => raise ParseError::InvalidSyntax(
          "invalid escape sequence: \\\{Char::from_int(bytes[i]) 
            |> Option::or("?")}",
        )
      }
    } else {
      result.write_char(
        Char::from_int(bytes[i]) |> Option::or("invalid char"),
      )
    }
    i += 1
  }
  if i >= len {
    raise ParseError::InvalidSyntax("unterminated string literal")
  }
  result.to_string()
}

/// Parse a TOML inline array like [1, 2, 3]
fn parse_array(s : String) -> TomlValue raise ParseError {
  if s.length() < 2 || s[0] != '[' {
    raise ParseError::InvalidSyntax("expected array, got: \{s}")
  }
  let len = s.length()
  if len == 2 {
    return TomlArray([])
  }
  let inner = s.sub(start=1, end=len - 1).to_owned().trim()
  let mut items : Array[TomlValue] = []
  let mut i = 0
  let inner_len = inner.length()
  while i < inner_len {
    // skip whitespace
    while i < inner_len && inner[i] == ' ' {
      i += 1
    }
    if i >= inner_len {
      break
    }
    // Determine value type by first char
    if inner[i] == '[' {
      // Nested array - find matching ]
      let mut depth = 1
      let arr_start = i
      i += 1
      while i < inner_len && depth > 0 {
        if inner[i] == '[' {
          depth += 1
        } else if inner[i] == ']' {
          depth -= 1
        }
        i += 1
      }
      if depth != 0 {
        raise ParseError::InvalidSyntax("unmatched bracket in nested array")
      }
      let arr_str = inner.sub(start=arr_start, end=i).to_owned()
      items.push(parse_array(arr_str)?)
    } else if inner[i] == '"' {
      // String value
      let str_start = i
      i += 1
      while i < inner_len && not(inner[i] == '"' && inner[i - 1] != '\\') {
        i += 1
      }
      i += 1 // closing quote
      let str_val = inner.sub(start=str_start, end=i).to_owned()
      items.push(TomlString(parse_string(str_val)?))
    } else {
      // Number, bool, or other simple value - read until comma or end
      let val_start = i
      while i < inner_len && inner[i] != ',' {
        i += 1
      }
      let val_str = inner.sub(start=val_start, end=i).to_owned().trim()
      items.push(parse_value(val_str)?)
    }
    // Skip comma
    if i < inner_len && inner[i] == ',' {
      i += 1
    }
  }
  TomlArray(items)
}

/// Ensure a table path exists in the table, creating intermediate tables as needed
fn ensure_table(
  table : Map[Array[String], TomlValue],
  path : Array[String]
) -> Unit raise ParseError {
  for i in 0..<path.length() {
    let prefix = path[0..i] + [path[i]]
    if table.contains(prefix) {
      match table[prefix] {
        TomlTable(_) => continue
        _ => {
          raise ParseError::DuplicateKey(
            "cannot create table \{prefix.join(".")}; key already exists as a non-table",
          )
        }
      }
    }
    // First time seeing this prefix, it's implicitly empty
    ()
  }
  // Register the full path as a table
  table.insert(path, TomlTable(Map::new()))
}

/// Build a JSON value from the parsed key-path table
fn build_json(table : Map[Array[String], TomlValue]) -> Json raise ParseError {
  build_subtree(table, [])
}

/// Build JSON recursively from key-value entries under a given prefix
fn build_subtree(
  table : Map[Array[String], TomlValue],
  prefix : Array[String]
) -> Json raise ParseError {
  let mut obj_map = Map::new()
  // Collect all keys directly under this prefix
  let mut child_keys : Map[String, Array[String]] = Map::new()
  for path, value in table {
    if path.length() <= prefix.length() {
      continue
    }
    // Check if it starts with prefix
    let mut matches = true
    for j in 0..<prefix.length() {
      if j >= path.length() || path[j] != prefix[j] {
        matches = false
        break
      }
    }
    if not matches {
      continue
    }
    // It's under this prefix. The first component after prefix is the key
    // under which we place this value (or a sub-object)
    let key = path[prefix.length()]
    if path.length() == prefix.length() + 1 {
      // Direct child
      obj_map[key] = toml_to_json(value)
    } else {
      // Deeper - need a sub-object
      child_keys[key] = path
    }
  }

  // Build sub-objects for deeper paths
  for key, _ in child_keys {
    if not obj_map.contains(key) {
      let sub_prefix = prefix + [key]
      obj_map[key] = build_subtree(table, sub_prefix)?
    }
  }

  Json::object(obj_map)
}

/// Convert a TomlValue to Json
fn toml_to_json(v : TomlValue) -> Json {
  match v {
    TomlString(s) => Json::string(s)
    TomlInt(n) => Json::number(
      n.to_double(),
      repr=n.to_string(),
    )
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(toml_to_json))
    TomlTable(t) => {
      let m = Map::new()
      for k, v in t {
        m[k] = toml_to_json(v)
      }
      Json::object(m)
    }
  }
}
