          raise ParseError::InvalidSyntax(
            "invalid escape sequence: \\\{Char::from_int(code) 
              |> Option::or("?")}",
          )
        }
      }
    } else {
      let ch = Char::from_int(s[i])
      match ch {
        Some(c) => result.write_char(c)
        None => raise ParseError::InvalidSyntax("invalid character in string")
      }
    }
    i += 1
  }
  if i >= len {
    raise ParseError::InvalidSyntax("unterminated string literal")
  }
  result.to_string()
}

/// Parse a TOML inline array like [1, 2, 3]
fn parse_array(s : String) -> TomlValue raise ParseError {
  let len = s.length()
  if len < 2 || s[0] != '[' {
    raise ParseError::InvalidSyntax("expected array, got: \{s}")
  }
  // Find matching close bracket
  let mut depth = 0
  let mut close_pos = -1
  for i in 0..<len {
    if s[i] == '[' {
      depth += 1
    } else if s[i] == ']' {
      depth -= 1
      if depth == 0 {
        close_pos = i
        break
      }
    }
  }
  if close_pos != len - 1 || depth != 0 {
    raise ParseError::InvalidSyntax("unmatched bracket in array: \{s}")
  }
  if len == 2 {
    return TomlArray([])
  }
  let inner = s.sub(start=1, end=len - 1).to_owned().trim()
  if inner.is_empty() {
    return TomlArray([])
  }
  let mut items : Array[TomlValue] = []
  split_array_elements(inner, items)
  TomlArray(items)
}

fn split_array_elements(inner : String, items : Array[TomlValue]) -> Unit raise ParseError {
  let len = inner.length()
  let mut i = 0
  while i < len {
    // skip whitespace and commas
    while i < len && (inner[i] == ' ' || inner[i] == ',') {
      i += 1
    }
    if i >= len {
      break
    }
    // Determine value type by first char
    if inner[i] == '[' {
      // Nested array - find matching ]
      let arr_start = i
      let mut depth = 1
      i += 1
      while i < len && depth > 0 {
        if inner[i] == '[' {
          depth += 1
        } else if inner[i] == ']' {
          depth -= 1
        }
        i += 1
      }
      if depth != 0 {
        raise ParseError::InvalidSyntax("unmatched bracket in nested array")
      }
      let arr_str = inner.sub(start=arr_start, end=i).to_owned()
      items.push(parse_array(arr_str))
    } else if inner[i] == '"' {
      // String value
      let str_start = i
      i += 1
      while i < len && not(inner[i] == '"' && inner[i - 1] != '\\') {
        i += 1
      }
      i += 1 // closing quote
      let str_val = inner.sub(start=str_start, end=i).to_owned()
      items.push(TomlString(parse_string(str_val)))
    } else {
      // Number, bool, or other simple value - read until comma or end
      let val_start = i
      while i < len && inner[i] != ',' && inner[i] != ' ' {
        i += 1
      }
      let val_str = inner.sub(start=val_start, end=i).to_owned().trim()
      items.push(parse_value(val_str))
    }
  }
