/// Ensure a table path exists, creating intermediate tables as needed
fn ensure_table(
  table : Map[Array[String], TomlValue],
  path : Array[String]
) -> Unit raise ParseError {
  for i in 0..<path.length() {
    let prefix = path[0..i] + [path[i]]
    if table.contains(prefix) {
      match table[prefix] {
        TomlTable(_) => continue
        _ => {
          raise ParseError::DuplicateKey(
    "cannot create table \{prefix.join(".")}; key already exists as a non-table",
          )
        }
      }
    }
    // First time seeing this prefix, register as empty table
    table.insert(prefix, TomlTable(Map::new()))
  }
  // Register the full path as a table
  table.insert(path, TomlTable(Map::new()))
}

/// Build JSON from key-path table entries
fn build_json(
  table : Map[Array[String], TomlValue],
  prefix : Array[String]
) -> Json raise ParseError {
  let mut obj_map = Map::new()

  // Collect all paths that start with prefix
  for path, value in table {
    if path.length() <= prefix.length() {
      continue
    }
    let mut matches = true
    for j in 0..<prefix.length() {
      if j >= path.length() || path[j] != prefix[j] {
        matches = false
        break
      }
    }
    if not matches {
      continue
    }
    // The first component after prefix is the immediate key
    let key = path[prefix.length()]
    if path.length() == prefix.length() + 1 {
      // Direct child - only add if not already present (later entries override)
      if not obj_map.contains(key) {
        obj_map[key] = toml_to_json(value)
      }
    } else {
      // Deeper path - might need a sub-object
      if not obj_map.contains(key) {
        // Create the sub-object on first occurrence
        if prefix.length() + 1 < path.length() {
          let sub_value = table[path]
          obj_map[key] = toml_to_json(sub_value)
        }
      }
    }
  }

  // Now, for keys that have deeper paths, we need to build their sub-trees
  // Collect all unique first-level keys under this prefix
  let first_keys : Map[String, Bool] = Map::new()
  for path, _ in table {
    if path.length() <= prefix.length() {
      continue
    }
    let mut matches = true
    for j in 0..<prefix.length() {
      if j >= path.length() || path[j] != prefix[j] {
        matches = false
        break
      }
    }
    if not matches {
      continue
    }
    let key = path[prefix.length()]
    first_keys[key] = true
  }

  for key, _ in first_keys {
    if not obj_map.contains(key) {
      // This key only has sub-entries; build sub-object
      let new_prefix = prefix + [key]
      obj_map[key] = build_json(table, new_prefix)
    }
  }

  Json::object(obj_map)
}

/// Convert a TomlValue to Json
fn toml_to_json(v : TomlValue) -> Json {
  match v {
    TomlString(s) => Json::string(s)
    TomlInt(n) => Json::number(
      n.to_double(),
      repr=n.to_string(),
    )
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(toml_to_json))
    TomlTable(t) => {
      let m = Map::new()
      for k, v in t {
        m[k] = toml_to_json(v)
      }
      Json::object(m)
    }
  }
}
