        break
      }
    }
  }
  if close_pos != len - 1 || depth != 0 {
    raise ParseError::InvalidSyntax("unmatched bracket in array: \{s}")
  }
  if len == 2 {
    return TomlArray([])
  }
  let inner = s.sub(start=1, end=len - 1).to_owned().trim().to_owned()
  if inner.is_empty() {
