    if i >= len {
      break
    }
    // Determine value type by first char
    if inner[i] == '[' {
      // Nested array - find matching ]
      let arr_start = i
      let mut depth = 1
      i += 1
      while i < len && depth > 0 {
        if inner[i] == '[' {
