        }
        i += 1
      }
      if depth != 0 {
        raise ParseError::InvalidSyntax("unmatched bracket in nested array")
      }
      let arr_str = inner.sub(start=arr_start, end=i).to_owned()
      items.push(parse_array(arr_str))
    } else if inner[i] == '"' {
