// Generated using `moon info`, DON'T EDIT IT
package "user/toml/lib"

import {
  "moonbitlang/core/debug",
}

// Values
pub fn parse(String) -> Json raise ParseError

// Errors
pub suberror ParseError {
  InvalidSyntax(String)
  DuplicateKey(String)
} derive(@debug.Debug)

// Types and methods

// Type aliases

// Traits

///|
/// Internal representation of a TOML value
priv enum TomlValue {
  TomlString(String)
  TomlInt(Int64)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
  TomlTable(Map[String, TomlValue])
}

///|
/// Parse TOML text into a JSON value
pub fn parse(text : String) -> Json raise ParseError {
  let table : Map[Array[String], TomlValue] = Map([])
  let mut current_path : Array[String] = []

  for line_view in text.split("\n") {
    let line_view = line_view.trim()
    let line = line_view.to_owned()
    if line.is_empty() || line[0] == '#' {
      continue
    }

    if line[0] == '[' {
      let close = find_closing_bracket(line, 0)
      if close == -1 {
        raise ParseError::InvalidSyntax("unclosed table bracket: \{line}")
      }
      let key_part = line.sub(start=1, end=close).to_owned()
      let remainder = line.sub(start=close + 1, end=line.length()).to_owned()
      let trimmed_remainder = remainder.trim().to_owned()
      if !trimmed_remainder.is_empty() && trimmed_remainder[0] != '#' {
        raise ParseError::InvalidSyntax(
          "trailing junk after table header: \{trimmed_remainder}",
        )
      }
      current_path = parse_dotted_key(key_part)
      continue
    }

    let eq_pos = find_eq(line, 0)
    if eq_pos == -1 {
      raise ParseError::InvalidSyntax("expected key=value, got: \{line}")
    }
    let key_str = line.sub(start=0, end=eq_pos).to_owned().trim().to_owned()
    let val_str = line
      .sub(start=eq_pos + 1, end=line.length())
      .to_owned()
      .trim()
      .to_owned()
    let key_parts = parse_dotted_key(key_str)
    let val = parse_value(val_str)

    let full_path = current_path + key_parts
    if table.contains(full_path) {
      let path_str = full_path.join(".")
      raise ParseError::DuplicateKey(path_str)
    }
    table[full_path] = val
  }

  build_json(table, [])
}

///|
fn find_closing_bracket(s : String, start : Int) -> Int {
  let len = s.length()
  let mut i = start + 1
  while i < len {
    if s[i] == ']' {
      return i
    }
    i += 1
  }
  -1
}

///|
fn find_eq(s : String, start : Int) -> Int {
  let len = s.length()
  let mut i = start
  while i < len {
    if s[i] == '=' {
      return i
    }
    i += 1
  }
  -1
}

///|
fn parse_dotted_key(s : String) -> Array[String] raise ParseError {
  if s.is_empty() {
    raise ParseError::InvalidSyntax("empty key")
  }
  let parts : Array[String] = []
  let mut start = 0
  let len = s.length()
  while start < len {
    if s[start] == '.' {
      start += 1
      continue
    }
    let mut end = start
    while end < len && s[end] != '.' {
      end += 1
    }
    let part = s.sub(start~, end~).to_owned()
    if part.is_empty() {
      raise ParseError::InvalidSyntax("empty key segment in: \{s}")
    }
    parts.push(part)
    start = end
  }
  parts
}

///|
fn parse_value(s : String) -> TomlValue raise ParseError {
  let trimmed = s.trim().to_owned()
  if trimmed.is_empty() {
    raise ParseError::InvalidSyntax("empty value")
  }

  if trimmed[0] == '[' {
    return parse_array(trimmed)
  }

  if trimmed[0] == '"' {
    return TomlString(parse_string(trimmed))
  }

  if trimmed == "true" {
    return TomlBool(true)
  }
  if trimmed == "false" {
    return TomlBool(false)
  }

  let n : Int64? = Some(@string.parse_int64(trimmed)) catch { _ => None }
  if n is Some(v) {
    return TomlInt(v)
  }

  raise ParseError::InvalidSyntax("unrecognised value: \{trimmed}")
}

///|
fn parse_string(s : String) -> String raise ParseError {
  let len = s.length()
  if len < 2 || s[0] != '"' {
    raise ParseError::InvalidSyntax("expected quoted string, got: \{s}")
  }
  let i = 1
  let result = StringBuilder::new()
  parse_string_inner(s, i, result)
}

///|
fn parse_string_inner(
  s : String,
  start : Int,
  result : StringBuilder,
) -> String raise ParseError {
  let len = s.length()
  let mut i = start
  while i < len {
    let ch = s[i]
    if ch == '"' {
      return result.to_string()
    }
    if ch == '\\' {
      i += 1
      if i >= len {
        raise ParseError::InvalidSyntax("unterminated escape in string")
      }
      let esc = s[i]
      if esc == '"' {
        result.write_char('"')
      } else if esc == '\\' {
        result.write_char('\\')
      } else if esc == 'n' {
        result.write_char('\n')
      } else if esc == 't' {
        result.write_char('\t')
      } else {
        let code = esc.to_int()
        let msg = "invalid escape sequence: \\" +
          code.unsafe_to_char().to_string()
        raise ParseError::InvalidSyntax(msg)
      }
    } else {
      let code = ch.to_int()
      result.write_char(code.unsafe_to_char())
    }
    i += 1
  }
  raise ParseError::InvalidSyntax("unterminated string literal")
}

///|
fn parse_array(s : String) -> TomlValue raise ParseError {
  let len = s.length()
  if len < 2 || s[0] != '[' {
    raise ParseError::InvalidSyntax("expected array, got: \{s}")
  }
  let mut depth = 0
  let mut close_pos = -1
  for i in 0..<len {
    if s[i] == '[' {
      depth += 1
    } else if s[i] == ']' {
      depth -= 1
      if depth == 0 {
        close_pos = i
        break
      }
    }
  }
  if close_pos != len - 1 || depth != 0 {
    raise ParseError::InvalidSyntax("unmatched bracket in array: \{s}")
  }
  if len == 2 {
    return TomlArray([])
  }
  let inner = s.sub(start=1, end=len - 1).to_owned().trim().to_owned()
  if inner.is_empty() {
    return TomlArray([])
  }
  let items : Array[TomlValue] = []
  split_array_elements(inner, items)
  TomlArray(items)
}

///|
fn split_array_elements(
  inner : String,
  items : Array[TomlValue],
) -> Unit raise ParseError {
  let len = inner.length()
  let mut i = 0
  while i < len {
    while i < len && (inner[i] == ' ' || inner[i] == ',') {
      i += 1
    }
    if i >= len {
      break
    }
    if inner[i] == '[' {
      let arr_start = i
      let mut depth = 1
      i += 1
      while i < len && depth > 0 {
        if inner[i] == '[' {
          depth += 1
        } else if inner[i] == ']' {
          depth -= 1
        }
        i += 1
      }
      if depth != 0 {
        raise ParseError::InvalidSyntax("unmatched bracket in nested array")
      }
      let arr_str = inner.sub(start=arr_start, end=i).to_owned()
      items.push(parse_array(arr_str))
    } else if inner[i] == '"' {
      let str_start = i
      i += 1
      while i < len && !(inner[i] == '"' && inner[i - 1] != '\\') {
        i += 1
      }
      i += 1
      let str_val = inner.sub(start=str_start, end=i).to_owned()
      items.push(TomlString(parse_string(str_val)))
    } else {
      let val_start = i
      while i < len && inner[i] != ',' && inner[i] != ' ' {
        i += 1
      }
      let val_str = inner
        .sub(start=val_start, end=i)
        .to_owned()
        .trim()
        .to_owned()
      items.push(parse_value(val_str))
    }
  }
}

///|
fn build_json(
  table : Map[Array[String], TomlValue],
  prefix : Array[String],
) -> Json raise ParseError {
  let obj_map : Map[String, Json] = Map([])

  // First pass: find all direct children
  for path, value in table {
    if path.length() == prefix.length() + 1 {
      let mut matches = true
      for j in 0..<prefix.length() {
        if j >= path.length() || path[j] != prefix[j] {
          matches = false
          break
        }
      }
      if matches {
        let key = path[prefix.length()]
        if !obj_map.contains(key) {
          obj_map[key] = toml_to_json(value)
        }
      }
    }
  }

  // Second pass: find keys that need sub-objects (paths longer than prefix+1)
  let sub_keys : Map[String, Bool] = Map([])
  for path, _ in table {
    if path.length() <= prefix.length() + 1 {
      continue
    }
    let mut matches = true
    for j in 0..<prefix.length() {
      if j >= path.length() || path[j] != prefix[j] {
        matches = false
        break
      }
    }
    if matches {
      let key = path[prefix.length()]
      sub_keys[key] = true
    }
  }

  for key, _ in sub_keys {
    if !obj_map.contains(key) {
      let new_prefix = prefix + [key]
      obj_map[key] = build_json(table, new_prefix)
    }
  }

  Json::object(obj_map)
}

///|
fn toml_to_json(v : TomlValue) -> Json {
  match v {
    TomlString(s) => Json::string(s)
    TomlInt(n) => Json::number(n.to_double(), repr=n.to_string())
    TomlBool(b) => Json::boolean(b)
    TomlArray(a) => Json::array(a.map(toml_to_json))
    TomlTable(t) => {
      let m = Map([])
      for k, v in t {
        m[k] = toml_to_json(v)
      }
      Json::object(m)
    }
  }
}
